// Pre-rendered section pages (SEO option A), FR at root and EN under /en/.
// Build artifacts: regenerated by npm run refresh — never hand-edited.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';

const BASE = 'https://dossiercanada.ca';
const SRC = 'index.html';

// slug = filename (= URL via cleanUrls); view = #view-... id
// NOTE: data-view "ministres" is the MPs tab; "cabinet" is the Ministers tab.
const SECTIONS = [
  { slug:'deputes', view:'ministres',
    title:{ fr:'Députés de la Chambre des communes — DossierCanada', en:'Members of the House of Commons — DossierCanada' },
    desc:{ fr:'Les 343 sièges de la Chambre des communes : nom, circonscription, parti et taux de présence de chaque député·e. Données officielles, en clair.',
           en:'All 343 seats in the House of Commons: name, riding, party and attendance rate for each MP. Official data, in plain language.' } },
  { slug:'ministres', view:'cabinet',
    title:{ fr:'Le Cabinet fédéral — DossierCanada', en:'The federal Cabinet — DossierCanada' },
    desc:{ fr:'Le Conseil des ministres du Canada : qui décide quoi, depuis quand, et comment iel vote. Sourcé de pm.gc.ca.',
           en:"Canada's Cabinet: who decides what, since when, and how they vote. Sourced from pm.gc.ca." } },
  { slug:'projets-de-loi', view:'projets',
    title:{ fr:'Projets de loi du Parlement du Canada — DossierCanada', en:"Bills in Canada's Parliament — DossierCanada" },
    desc:{ fr:'Tous les projets de loi au Parlement du Canada, résumés en langage clair : étape, statut, parrain et votes. Sans jugement.',
           en:"Every bill in Canada's Parliament, summarized in plain language: stage, status, sponsor and votes. No spin." } },
  { slug:'votes', view:'votes',
    title:{ fr:'Registre des votes de la Chambre des communes — DossierCanada', en:'House of Commons recorded votes — DossierCanada' },
    desc:{ fr:"Chaque vote nominatif à la Chambre des communes : qui a voté pour, contre ou s'est fait pairer, et par quelle marge. Le registre officiel, tel quel.",
           en:'Every recorded vote in the House of Commons: who voted yea, nay or paired, and by what margin. The official record, as published.' } },
  { slug:'lexique', view:'lexique',
    title:{ fr:'Lexique parlementaire — DossierCanada', en:'Parliamentary glossary — DossierCanada' },
    desc:{ fr:'Le jargon du Parlement du Canada traduit en français de tous les jours, plus les personnes et institutions qui gravitent autour.',
           en:"Parliament's jargon translated into everyday English, plus the people and institutions around it." } }
];

const HOME = {
  title: { fr:'DossierCanada — Qui siège, qui légifère, qui vote quoi', en:'DossierCanada — Who sits, who legislates, who votes how' },
  desc: { fr:'Site citoyen indépendant qui suit le Parlement du Canada — députés, projets de loi, votes — en clair et sans jugement.',
          en:"Independent citizen-run site tracking Canada's Parliament — MPs, bills, votes — in plain language." }
};

const raw = readFileSync(SRC, 'utf8');
const NL = raw.includes('\r\n') ? '\r\n' : '\n';
const src = raw;

function must(cond, msg){ if(!cond){ console.error('build-section-pages: ' + msg); process.exit(1); } }
must(src.includes('<section class="view active" id="view-apercu">'), 'active home view missing');
must(/<button class="active" data-view="apercu"/.test(src), 'active home nav button missing');

const esc = s => s.replace(/"/g, '&quot;');

function setHreflang(h, frPath, enPath){
  const frUrl = BASE + frPath;
  const enUrl = BASE + enPath;
  if (/rel="alternate" hreflang="fr"/.test(h)) {
    h = h.replace(/<link rel="alternate" hreflang="fr" href="[^"]*">/, '<link rel="alternate" hreflang="fr" href="' + frUrl + '">');
    h = h.replace(/<link rel="alternate" hreflang="en" href="[^"]*">/, '<link rel="alternate" hreflang="en" href="' + enUrl + '">');
    h = h.replace(/<link rel="alternate" hreflang="x-default" href="[^"]*">/, '<link rel="alternate" hreflang="x-default" href="' + frUrl + '">');
  } else {
    h = h.replace(/(<link rel="canonical" href="[^"]*">)/, '$1' + NL
      + '<link rel="alternate" hreflang="fr" href="' + frUrl + '">' + NL
      + '<link rel="alternate" hreflang="en" href="' + enUrl + '">' + NL
      + '<link rel="alternate" hreflang="x-default" href="' + frUrl + '">');
  }
  return h;
}

function setMeta(h, { title, desc, url }){
  h = h.replace(/<title>[^<]*<\/title>/, '<title>' + title + '</title>');
  h = h.replace(/(<meta name="description" content=")[^"]*(">)/, '$1' + esc(desc) + '$2');
  h = h.replace(/(<link rel="canonical" href=")[^"]*(">)/, '$1' + url + '$2');
  h = h.replace(/(<meta property="og:title" content=")[^"]*(">)/, '$1' + esc(title) + '$2');
  h = h.replace(/(<meta property="og:description" content=")[^"]*(">)/, '$1' + esc(desc) + '$2');
  h = h.replace(/(<meta property="og:url" content=")[^"]*(">)/, '$1' + url + '$2');
  h = h.replace(/(<meta name="twitter:title" content=")[^"]*(">)/, '$1' + esc(title) + '$2');
  h = h.replace(/(<meta name="twitter:description" content=")[^"]*(">)/, '$1' + esc(desc) + '$2');
  return h;
}

function activateView(h, view){
  h = h.replace('<section class="view active" id="view-apercu">', '<section class="view" id="view-apercu">');
  const secFrom = '<section class="view" id="view-' + view + '">';
  must(h.includes(secFrom), 'section #view-' + view + ' missing');
  h = h.replace(secFrom, '<section class="view active" id="view-' + view + '">');
  h = h.replace('<button class="active" data-view="apercu"', '<button data-view="apercu"');
  const navRe = new RegExp('<button data-view="' + view + '"');
  must(navRe.test(h), 'nav button data-view="' + view + '" missing');
  h = h.replace(navRe, '<button class="active" data-view="' + view + '"');
  return h;
}

function buildPage({ slug, view, lang }){
  const sec = SECTIONS.find(s => s.slug === slug);
  const isEn = lang === 'en';
  const path = isEn ? '/en/' + slug : '/' + slug;
  let html = src;
  html = setMeta(html, { title: sec.title[lang], desc: sec.desc[lang], url: BASE + path });
  html = setHreflang(html, '/' + slug, '/en/' + slug);
  html = activateView(html, view);
  if (isEn) {
    html = html.replace('<html lang="fr"', '<html lang="en"');
    mkdirSync('en', { recursive: true });
    writeFileSync('en/' + slug + '.html', html, 'utf8');
    console.log('ok en/' + slug + '.html');
  } else {
    writeFileSync(slug + '.html', html, 'utf8');
    console.log('ok ' + slug + '.html');
  }
}

function buildHomeEn(){
  let html = src;
  html = setMeta(html, { title: HOME.title.en, desc: HOME.desc.en, url: BASE + '/en' });
  html = setHreflang(html, '/', '/en');
  html = html.replace('<html lang="fr"', '<html lang="en"');
  writeFileSync('en.html', html, 'utf8');
  console.log('ok en.html');
}

SECTIONS.forEach(sec => buildPage({ slug: sec.slug, view: sec.view, lang: 'fr' }));
SECTIONS.forEach(sec => buildPage({ slug: sec.slug, view: sec.view, lang: 'en' }));
buildHomeEn();
console.log('done ' + (SECTIONS.length * 2 + 1) + ' pages');